func NormalizeProvider(provider, model string) string {
	provider = strings.ToLower(strings.TrimSpace(provider))
	provider = strings.TrimPrefix(provider, "eino/")
	provider = strings.ReplaceAll(provider, "_", "-")
	switch provider {
