		return ProviderOpenRouter
	case "azure", "azure-openai":
		return ProviderAzure
	case "google-paxton-reed", "google (user@example.com)":
		return ProviderGooglePaxtonReed
	case "google-acme", "google (user@example.com)":
		return ProviderGoogleacme
	case "google", "gemini":
		return ProviderGoogle
	case "openai", "openai-compatible", "openai-compatible-provider":
		return ProviderOpenAICompatible
	}

	model = strings.ToLower(strings.TrimSpace(model))
	switch {
	case strings.HasPrefix(model, "gemini-"), strings.HasPrefix(model, "models/gemini-"):
		return ProviderGoogle
	case isGPTFamilyModel(model), strings.HasPrefix(model, "o1"), strings.HasPrefix(model, "o3"), strings.HasPrefix(model, "o4"):
		return ProviderAzure
	default:
		return ProviderGoogle
	}
}

func isGPTFamilyModel(model string) bool {
	baseModel := strings.ToLower(strings.TrimSpace(model))
	if separator := strings.Index(baseModel, "::"); separator > 0 {
		baseModel = baseModel[:separator]
	}
	return strings.HasPrefix(baseModel, "gpt-") ||
		strings.HasPrefix(baseModel, "chatgpt-") ||
		strings.HasPrefix(baseModel, "azuregpt-")
}

func ProviderForDirectRuntime(provider string) string {
	switch NormalizeProvider(provider, "") {
	case ProviderGooglePaxtonReed:
		return utils.GooglePaxtonReedProvider
	case ProviderGoogleacme:
		return utils.GoogleacmeProvider
	case ProviderOpenRouter:
		return "OpenRouter"
	case ProviderAzure:
		return "Azure"
	case ProviderOpenAICompatible:
		return "OpenAI"
	default:
		return "Google"
	}
}

